CREATE TYPE public.app_role AS ENUM ('cuidador','operador','mestre');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, username text NOT NULL UNIQUE, must_change boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT normalized_username CHECK (username = lower(username) AND username ~ '^[a-z0-9_.-]{3,40}$'));
GRANT SELECT ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'cuidador');
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid() OR public.has_role(auth.uid(),'mestre') OR public.has_role(auth.uid(),'operador'));
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(),'mestre') OR public.has_role(auth.uid(),'operador'));
CREATE FUNCTION public.handle_new_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,username) VALUES (new.id, lower(new.raw_user_meta_data->>'username')); INSERT INTO public.user_roles(user_id,role) VALUES (new.id,'cuidador'); RETURN new; END $$;
CREATE TRIGGER dose_certa_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_account();
CREATE TABLE public.app_records (id text PRIMARY KEY, kind text NOT NULL CHECK (kind IN ('patients','meds','doses','alerts','tickets','config')), owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, payload jsonb NOT NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.app_records TO authenticated;
GRANT ALL ON public.app_records TO service_role;
ALTER TABLE public.app_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY records_read ON public.app_records FOR SELECT TO authenticated USING (owner_id = auth.uid() OR public.has_role(auth.uid(),'mestre') OR (public.has_role(auth.uid(),'operador') AND kind IN ('patients','meds','doses','tickets')) OR kind = 'config');
CREATE POLICY records_insert ON public.app_records FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(),'mestre') OR (owner_id = auth.uid() AND kind <> 'config'));
CREATE POLICY records_update ON public.app_records FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'mestre') OR (owner_id = auth.uid() AND kind <> 'config') OR (kind = 'tickets' AND public.has_role(auth.uid(),'operador'))) WITH CHECK (public.has_role(auth.uid(),'mestre') OR (owner_id = auth.uid() AND kind <> 'config') OR (kind = 'tickets' AND public.has_role(auth.uid(),'operador')));
CREATE POLICY records_delete ON public.app_records FOR DELETE TO authenticated USING (public.has_role(auth.uid(),'mestre') OR (owner_id = auth.uid() AND kind <> 'config'));
ALTER PUBLICATION supabase_realtime ADD TABLE public.profiles, public.user_roles, public.app_records;